<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\ValidationException;

class SchoolController extends Controller
{
    private function user(): array { return session('school_user', []); }
    private function requireRole(array $roles): array
    {
        $u = $this->user(); abort_unless($u && in_array($u['role'], $roles, true), 403); return $u;
    }
    public function home() { return view('home'); }
    public function loginForm() { return view('auth', ['mode'=>'login']); }
    public function registerForm() { return view('auth', ['mode'=>'register']); }
    public function login(Request $r)
    {
        $data=$r->validate(['email'=>'required|email','password'=>'required']);
        $u=DB::table('users')->whereRaw('LOWER(email)=?', [strtolower($data['email'])])->where('is_active',1)->first();
        if (!$u || !Hash::check($data['password'],$u->password)) return back()->withInput()->with('error','Email atau password tidak sesuai.');
        $profile=$this->profile($u); $r->session()->regenerate(); $r->session()->put('school_user',$profile);
        return redirect('/dashboard')->with('success','Selamat datang, '.$u->name.'!');
    }
    public function apiLogin(Request $r)
    {
        if ($r->isMethod('OPTIONS')) return response()->json(['ok'=>true]);
        $d=$r->validate(['email'=>'required|email','password'=>'required']);
        $u=DB::table('users')->whereRaw('LOWER(email)=?', [strtolower($d['email'])])->where('is_active',1)->first();
        if (!$u || !Hash::check($d['password'],$u->password)) return response()->json(['ok'=>false,'message'=>'Email atau password tidak sesuai.'],401);
        $profile=$this->profile($u); $r->session()->regenerate(); $r->session()->put('school_user',$profile);
        return response()->json(['ok'=>true,'message'=>'Login berhasil.','redirect'=>url('/dashboard'),'user'=>$profile]);
    }
    public function apiMe() { $u=$this->user(); return $u ? response()->json(['ok'=>true,'user'=>$u]) : response()->json(['ok'=>false,'message'=>'Belum login.'],401); }
    private function profile(object $u): array
    {
        $row=(array)$u; unset($row['password']); $row['user_id']=$u->id;
        if ($u->role==='siswa') { $p=DB::table('students')->where('user_id',$u->id)->first(); if($p) $row=array_merge($row,(array)$p,['user_id'=>$u->id]); }
        if ($u->role==='guru') { $p=DB::table('teachers')->where('user_id',$u->id)->first(); if($p) $row=array_merge($row,(array)$p,['user_id'=>$u->id,'subject'=>$p->main_subject]); }
        if ($u->role==='ortu') { $p=DB::table('parents')->where('user_id',$u->id)->first(); if($p){$s=DB::table('parent_students')->join('students','students.id','=','parent_students.student_id')->where('parent_id',$p->id)->value('student_code'); $row=array_merge($row,(array)$p,['user_id'=>$u->id,'child_code'=>$s??'']);} }
        return $row;
    }
    public function register(Request $r)
    {
        $d=$r->validate(['name'=>'required|string|max:150','email'=>'required|email|unique:users,email','password'=>'required|min:6','role'=>'required|in:siswa,guru,ortu','class_name'=>'nullable|string|max:80','subject'=>'nullable|string|max:100','child_code'=>'nullable|string|max:20']);
        $uid=DB::transaction(function() use($d) { $uid=DB::table('users')->insertGetId(['name'=>$d['name'],'email'=>strtolower($d['email']),'password'=>Hash::make($d['password']),'role'=>$d['role'],'is_active'=>1,'created_at'=>now(),'updated_at'=>now()]);
            if($d['role']==='siswa') DB::table('students')->insert(['user_id'=>$uid,'student_code'=>'SSK'.str_pad(DB::table('students')->max('id')+1,3,'0',STR_PAD_LEFT),'class_name'=>$d['class_name']??'X TKJ 1','major'=>'Teknik Komputer dan Jaringan','school_year'=>'2026/2027']);
            elseif($d['role']==='guru') DB::table('teachers')->insert(['user_id'=>$uid,'teacher_code'=>'GRU'.str_pad(DB::table('teachers')->max('id')+1,3,'0',STR_PAD_LEFT),'main_subject'=>$d['subject']??'Mata Pelajaran Umum']);
            else { $s=DB::table('students')->where('student_code',strtoupper($d['child_code']??''))->first(); if(!$s) throw ValidationException::withMessages(['child_code'=>'Kode siswa tidak ditemukan.']); $pid=DB::table('parents')->insertGetId(['user_id'=>$uid,'parent_code'=>'ORT'.str_pad(DB::table('parents')->max('id')+1,3,'0',STR_PAD_LEFT),'relationship'=>'wali']); DB::table('parent_students')->insert(['parent_id'=>$pid,'student_id'=>$s->id]); } return $uid; });
        $u=DB::table('users')->find($uid); $r->session()->regenerate(); $r->session()->put('school_user',$this->profile($u)); return redirect('/dashboard')->with('success','Akun berhasil dibuat.');
    }
    public function logout(Request $r) { $r->session()->invalidate(); $r->session()->regenerateToken(); return redirect('/login')->with('success','Anda telah keluar dari portal.'); }
    public function dashboard() { $u=$this->requireRole(['siswa','guru','ortu']); $materials=$this->materialRows(); $quizzes=$this->quizRows(); $sid=$u['role']==='ortu'?DB::table('parent_students')->where('parent_id',$u['id'])->value('student_id'):($u['role']==='siswa'?$u['id']:null); $results=$u['role']==='guru'?$this->resultRows():$this->resultRows($sid); $requests=$this->requestRows($u['role']==='siswa'?$u['id']:null); $child=$u['role']==='ortu'?DB::table('students')->join('users','users.id','=','students.user_id')->where('student_code',$u['child_code'])->select('students.*','users.name')->first():null; return view('dashboard',compact('u','materials','quizzes','results','requests','child')+['user'=>$u,'active'=>'dashboard','page_title'=>'Dashboard']); }
    public function academic() { if(($this->user()['role']??null)==='ortu') return redirect('/grades'); $u=$this->requireRole(['siswa','guru']); return view('academic',['user'=>$u,'active'=>'academic','page_title'=>'Materi Pembelajaran','materials'=>$this->materialRows()]); }
    public function quizzes() { if(($this->user()['role']??null)==='ortu') return redirect('/grades'); $u=$this->requireRole(['siswa','guru']); $results=$u['role']==='siswa'?$this->resultRows($u['id']):$this->resultRows(); return view('quizzes',['user'=>$u,'active'=>'quizzes','page_title'=>'Kuis','quizzes'=>$this->quizRows(),'results'=>$results]); }
    public function grades() { $u=$this->requireRole(['siswa','guru','ortu']); if($u['role']==='ortu'){$child=DB::table('students')->join('users','users.id','=','students.user_id')->where('student_code',$u['child_code'])->select('students.*','users.name')->first();$sid=$child->id??null;}else{$child=(object)$u;$sid=$u['role']==='siswa'?$u['id']:null;} $results=$u['role']==='guru'?$this->resultRows():$this->resultRows($sid); return view('grades',['user'=>$u,'active'=>'grades','page_title'=>'Nilai Kuis','student'=>$child,'results'=>$results]); }
    public function facilities() { if(($this->user()['role']??null)==='ortu') return redirect('/dashboard'); $u=$this->requireRole(['siswa','guru']); return view('facilities',['user'=>$u,'active'=>'facilities','page_title'=>'Fasilitas Sekolah','requests'=>$this->requestRows($u['role']==='siswa'?$u['id']:null),'facilities'=>DB::table('facilities')->where('is_active',1)->orderBy('name')->get()]); }
    private function materialRows() { return DB::table('materials')->join('subjects','subjects.id','=','materials.subject_id')->join('teachers','teachers.id','=','materials.teacher_id')->join('users','users.id','=','teachers.user_id')->where('materials.is_published',1)->select('materials.*','subjects.name as subject','teachers.id as teacher_id','users.name as teacher_name')->latest('materials.created_at')->get(); }
    private function saveMaterial(Request $r, array $u, ?int $id=null): void
    {
        $d=$r->validate(['title'=>'required|string|max:180','subject'=>'required|string|max:100','description'=>'nullable|string','material_file'=>'nullable|file|mimes:pdf,doc,docx,ppt,pptx,xls,xlsx,txt,zip|max:10240']);
        $sid=DB::table('subjects')->where('name',$d['subject'])->value('id');
        if(!$sid) $sid=DB::table('subjects')->insertGetId(['subject_code'=>strtoupper(substr(preg_replace('/[^a-z0-9]/i','',$d['subject']),0,8)).str_pad((string)random_int(1,99),2,'0',STR_PAD_LEFT),'name'=>$d['subject'],'description'=>'Mata pelajaran Smart School Kupang','teacher_id'=>$u['id'],'created_at'=>now()]);
        $values=['subject_id'=>$sid,'title'=>$d['title'],'description'=>$d['description']??''];
        if($r->hasFile('material_file')) { $f=$r->file('material_file'); $stored=$f->store('materials','public'); $values+=['file_name'=>$stored,'original_name'=>$f->getClientOriginalName(),'file_type'=>$f->extension(),'file_size'=>$f->getSize()]; }
        if($id) DB::table('materials')->where('id',$id)->where('teacher_id',$u['id'])->update($values+['updated_at'=>now()]);
        else DB::table('materials')->insert($values+['teacher_id'=>$u['id'],'is_published'=>1,'created_at'=>now(),'updated_at'=>now(),'original_name'=>$r->file('material_file')?->getClientOriginalName()??'Materi tanpa lampiran']);
    }
    public function uploadMaterial(Request $r) { $this->saveMaterial($r,$this->requireRole(['guru'])); return back()->with('success','Materi berhasil diterbitkan.'); }
    public function editMaterial(int $id) { $u=$this->requireRole(['guru']); $m=DB::table('materials')->join('subjects','subjects.id','=','materials.subject_id')->where('materials.id',$id)->where('materials.teacher_id',$u['id'])->select('materials.*','subjects.name as subject')->first(); abort_unless($m,404); return view('material-edit',['user'=>$u,'material'=>$m]); }
    public function updateMaterial(Request $r,int $id) { $u=$this->requireRole(['guru']); abort_unless(DB::table('materials')->where('id',$id)->where('teacher_id',$u['id'])->exists(),404); $this->saveMaterial($r,$u,$id); return redirect('/academic')->with('success','Materi berhasil diperbarui.'); }
    public function deleteMaterial(int $id) { $u=$this->requireRole(['guru']); DB::table('materials')->where('id',$id)->where('teacher_id',$u['id'])->update(['is_published'=>0,'updated_at'=>now()]); return back()->with('success','Materi berhasil dihapus.'); }
    public function downloadMaterial(int $id) { $this->requireRole(['siswa','guru']); $m=DB::table('materials')->join('subjects','subjects.id','=','materials.subject_id')->join('teachers','teachers.id','=','materials.teacher_id')->join('users','users.id','=','teachers.user_id')->where('materials.id',$id)->where('materials.is_published',1)->select('materials.*','subjects.name as subject','users.name as teacher_name')->first(); abort_unless($m,404); if($m->file_name && Storage::disk('public')->exists($m->file_name)) return Storage::disk('public')->download($m->file_name,$m->original_name); return response("SMART SCHOOL KUPANG\n\n{$m->title}\nMata Pelajaran: {$m->subject}\nGuru: {$m->teacher_name}\n\n{$m->description}")->header('Content-Disposition','attachment; filename="materi-'.$m->id.'.txt"'); }
    private function quizRows() { $rows=DB::table('quizzes')->join('subjects','subjects.id','=','quizzes.subject_id')->join('teachers','teachers.id','=','quizzes.teacher_id')->join('users','users.id','=','teachers.user_id')->where('quizzes.is_published',1)->select('quizzes.*','subjects.name as subject','teachers.id as teacher_id','users.name as teacher_name')->latest('quizzes.created_at')->get(); foreach($rows as $q){$q->questions=DB::table('quiz_questions')->where('quiz_id',$q->id)->orderBy('question_order')->get();} return $rows; }
    private function quizPayload(Request $r): array { $d=$r->validate(['title'=>'required|string|max:180','subject'=>'required|string|max:100','description'=>'nullable|string','question'=>'required|array|min:1|max:3','question.*'=>'nullable|string|max:2000','option_a'=>'array','option_b'=>'array','option_c'=>'array','option_d'=>'array','answer'=>'array']); $questions=[]; foreach($d['question'] as $i=>$text){if(trim((string)$text)==='') continue; $questions[]=['question_text'=>trim($text),'option_a'=>trim($d['option_a'][$i]??''),'option_b'=>trim($d['option_b'][$i]??''),'option_c'=>trim($d['option_c'][$i]??''),'option_d'=>trim($d['option_d'][$i]??''),'correct_answer'=>in_array($d['answer'][$i]??'', ['a','b','c','d'],true)?$d['answer'][$i]:'a','points'=>1,'question_order'=>count($questions)+1];} if(!$questions) throw ValidationException::withMessages(['question'=>'Isi minimal satu soal.']); return [$d,$questions]; }
    private function subjectId(string $name,int $teacherId): int { $id=DB::table('subjects')->where('name',$name)->value('id'); return $id ?: DB::table('subjects')->insertGetId(['subject_code'=>strtoupper(substr(md5($name),0,8)),'name'=>$name,'description'=>'Mata pelajaran Smart School Kupang','teacher_id'=>$teacherId,'created_at'=>now()]); }
    public function createQuiz(Request $r) { $u=$this->requireRole(['guru']); [$d,$qs]=$this->quizPayload($r); DB::transaction(function()use($d,$qs,$u){$id=DB::table('quizzes')->insertGetId(['subject_id'=>$this->subjectId($d['subject'],$u['id']),'teacher_id'=>$u['id'],'title'=>$d['title'],'description'=>$d['description']??null,'duration_minutes'=>30,'passing_score'=>75,'is_published'=>1,'created_at'=>now(),'updated_at'=>now()]); foreach($qs as $q) DB::table('quiz_questions')->insert($q+['quiz_id'=>$id,'created_at'=>now()]);}); return back()->with('success','Kuis berhasil diterbitkan.'); }
    public function editQuiz(int $id) { $u=$this->requireRole(['guru']); $q=collect($this->quizRows())->firstWhere('id',$id); abort_unless($q && $q->teacher_id==$u['id'],404); return view('quiz-edit',['user'=>$u,'quiz'=>$q]); }
    public function updateQuiz(Request $r,int $id) { $u=$this->requireRole(['guru']); abort_unless(DB::table('quizzes')->where('id',$id)->where('teacher_id',$u['id'])->exists(),404); [$d,$qs]=$this->quizPayload($r); DB::transaction(function()use($id,$u,$d,$qs){DB::table('quizzes')->where('id',$id)->update(['subject_id'=>$this->subjectId($d['subject'],$u['id']),'title'=>$d['title'],'description'=>$d['description']??null,'updated_at'=>now()]); DB::table('quiz_questions')->where('quiz_id',$id)->delete(); foreach($qs as $q) DB::table('quiz_questions')->insert($q+['quiz_id'=>$id,'created_at'=>now()]);}); return redirect('/quizzes')->with('success','Kuis berhasil diperbarui.'); }
    public function deleteQuiz(int $id) { $u=$this->requireRole(['guru']); DB::table('quizzes')->where('id',$id)->where('teacher_id',$u['id'])->update(['is_published'=>0,'updated_at'=>now()]); return back()->with('success','Kuis berhasil dihapus.'); }
    public function takeQuiz(int $id) { $u=$this->requireRole(['siswa']); $q=collect($this->quizRows())->firstWhere('id',$id); abort_unless($q,404); abort_if(DB::table('quiz_attempts')->where('quiz_id',$id)->where('student_id',$u['id'])->where('status','selesai')->exists(),409,'Kuis sudah dikerjakan.'); return view('quiz-take',['user'=>$u,'quiz'=>$q]); }
    public function submitQuiz(Request $r,int $id) { $u=$this->requireRole(['siswa']); $quiz=collect($this->quizRows())->firstWhere('id',$id); abort_unless($quiz,404); $answers=$r->input('answers',[]); $total=count($quiz->questions); abort_if($total===0,422); $correct=0; foreach($quiz->questions as $i=>$q) if(($answers[$i]??null)===$q->correct_answer) $correct++; $score=(int)round($correct/$total*100); try { DB::transaction(function()use($quiz,$u,$answers,$correct,$total,$score){$aid=DB::table('quiz_attempts')->insertGetId(['quiz_id'=>$quiz->id,'student_id'=>$u['id'],'score'=>$score,'correct_answers'=>$correct,'total_questions'=>$total,'submitted_at'=>now(),'status'=>'selesai']); foreach($quiz->questions as $i=>$q){$sel=$answers[$i]??null; DB::table('quiz_answers')->insert(['attempt_id'=>$aid,'question_id'=>$q->id,'selected_answer'=>in_array($sel,['a','b','c','d'],true)?$sel:null,'is_correct'=>$sel===$q->correct_answer,'points_earned'=>$sel===$q->correct_answer?1:0]);}}); } catch(\Illuminate\Database\QueryException $e){ return redirect('/quizzes')->with('error','Kuis ini sudah pernah dikerjakan.'); } return redirect('/quizzes')->with('success',"Kuis selesai. Nilai kamu: {$score}"); }
    public function quizResults(int $id) { $u=$this->requireRole(['guru']); $q=collect($this->quizRows())->firstWhere('id',$id); abort_unless($q && $q->teacher_id==$u['id'],404); $rows=DB::table('quiz_attempts')->join('students','students.id','=','quiz_attempts.student_id')->join('users','users.id','=','students.user_id')->where('quiz_id',$id)->where('status','selesai')->select('quiz_attempts.*','users.name as student_name','students.student_code')->orderByDesc('score')->get(); return view('quiz-results',['user'=>$u,'quiz'=>$q,'results'=>$rows]); }
    private function resultRows(?int $studentId=null) { $q=DB::table('quiz_attempts')->join('quizzes','quizzes.id','=','quiz_attempts.quiz_id')->join('students','students.id','=','quiz_attempts.student_id')->join('users','users.id','=','students.user_id')->where('quiz_attempts.status','selesai')->select('quiz_attempts.*','quizzes.title as quiz_title','users.name as student_name','students.student_code')->orderByDesc('submitted_at'); if($studentId) $q->where('quiz_attempts.student_id',$studentId); return $q->get(); }
    private function requestRows(?int $studentId=null) { $q=DB::table('facility_requests')->join('facilities','facilities.id','=','facility_requests.facility_id')->join('students','students.id','=','facility_requests.student_id')->join('users','users.id','=','students.user_id')->select('facility_requests.*','facilities.name as facility','students.student_code','users.name as student_name')->latest('facility_requests.created_at'); if($studentId) $q->where('facility_requests.student_id',$studentId); return $q->get(); }
    public function borrowFacility(Request $r) { $u=$this->requireRole(['siswa']); $d=$r->validate(['facility'=>'required|in:Laptop Praktik,Kamera DSLR,Proyektor Kelas,Ruang Multimedia','purpose'=>'required|string','date_needed'=>'required|date|after_or_equal:today']); $fid=DB::table('facilities')->where('name',$d['facility'])->where('is_active',1)->value('id'); abort_unless($fid,422); DB::table('facility_requests')->insert(['student_id'=>$u['id'],'facility_id'=>$fid,'purpose'=>$d['purpose'],'date_needed'=>$d['date_needed'],'status'=>'menunggu','created_at'=>now(),'updated_at'=>now()]); return back()->with('success','Pengajuan fasilitas berhasil dikirim kepada guru.'); }
    public function editFacility(int $id) { $u=$this->requireRole(['siswa']); $r=DB::table('facility_requests')->join('facilities','facilities.id','=','facility_requests.facility_id')->where('facility_requests.id',$id)->where('student_id',$u['id'])->select('facility_requests.*','facilities.name as facility')->first(); abort_unless($r,404); abort_unless($r->status==='menunggu',403,'Pengajuan sudah diproses.'); return view('facility-edit',['user'=>$u,'request'=>$r]); }
    public function updateFacility(Request $r,int $id) { $u=$this->requireRole(['siswa']); $d=$r->validate(['facility'=>'required|in:Laptop Praktik,Kamera DSLR,Proyektor Kelas,Ruang Multimedia','purpose'=>'required|string','date_needed'=>'required|date|after_or_equal:today']); $fid=DB::table('facilities')->where('name',$d['facility'])->value('id'); $n=DB::table('facility_requests')->where('id',$id)->where('student_id',$u['id'])->where('status','menunggu')->update(['facility_id'=>$fid,'purpose'=>$d['purpose'],'date_needed'=>$d['date_needed'],'updated_at'=>now()]); abort_unless($n,403,'Pengajuan sudah diproses.'); return redirect('/facilities')->with('success','Pengajuan fasilitas berhasil diperbarui.'); }
    public function deleteFacility(int $id) { $u=$this->requireRole(['siswa','guru']); $q=DB::table('facility_requests')->where('id',$id); if($u['role']==='siswa')$q->where('student_id',$u['id'])->where('status','menunggu'); abort_unless($q->delete(),404); return back()->with('success','Pengajuan fasilitas berhasil dihapus.'); }
    public function facilityStatus(int $id,string $status) { $u=$this->requireRole(['guru']); abort_unless(in_array($status,['menunggu','disetujui','ditolak','dipinjam','dikembalikan'],true),404); $n=DB::table('facility_requests')->where('id',$id)->update(['status'=>$status,'approved_by'=>in_array($status,['disetujui','ditolak'])?$u['id']:null,'approved_at'=>in_array($status,['disetujui','ditolak'])?now():null,'updated_at'=>now()]); abort_unless($n,404); return back()->with('success','Status pengajuan berhasil diperbarui.'); }}


